    float2 uv = float2((float(dtid.x) + 0.5f) / float(P.w), (float(dtid.y) + 0.5f) / float(P.h));
    dst[dtid.y * P.w + dtid.x] = tex.SampleLevel(linearClamp, uv, 0.0f);
